=== submission_01.ino ===
   1| // Lab 4 - debounced button toggle
   2| // D2 = button to GND (INPUT_PULLUP, reads LOW when pressed)
   3| // D13 = on-board LED
   4| // Serial1 @ 9600 prints the LED state on every toggle
   5| 
   6| const int BUTTON_PIN = 2;
   7| const int LED_PIN = 13;
   8| const unsigned long DEBOUNCE_MS = 5;   // input must be stable for 5 ms
   9| 
  10| int lastRaw = HIGH;          // raw reading last time through loop()
  11| int debounced = HIGH;        // accepted (debounced) button level
  12| unsigned long lastEdgeMs = 0;
  13| bool ledOn = false;
  14| 
  15| void setup() {
  16|   pinMode(BUTTON_PIN, INPUT_PULLUP);
  17|   pinMode(LED_PIN, OUTPUT);
  18|   digitalWrite(LED_PIN, LOW);   // start with LED off
  19|   Serial1.begin(9600);
  20| }
  21| 
  22| void loop() {
  23|   int raw = digitalRead(BUTTON_PIN);
  24| 
  25|   // any change restarts the debounce timer
  26|   if (raw != lastRaw) {
  27|     lastEdgeMs = millis();
  28|     lastRaw = raw;
  29|   }
  30| 
  31|   // accept the new level once it has been stable long enough
  32|   if (millis() - lastEdgeMs >= DEBOUNCE_MS && raw != debounced) {
  33|     debounced = raw;
  34| 
  35|     if (debounced == LOW) {   // button went down
  36|       Serial1.println(ledOn ? "ON" : "OFF");
  37|       ledOn = !ledOn;
  38|       digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  39|     }
  40|   }
  41| }
</student_code>
